output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "An agent must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "north_without_cart_only_in_narrow_aisle",
    "text": "Moving north without a cart is prohibited except when already in, or entering, a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "N"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "N",
          {
            "not": "hasCart"
          },
          {
            "not": "singleFileAisle"
          },
          {
            "not": "enterSingleFileOnFoot"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_walking_on_wide_floor",
    "text": "After leaving the entrance/cart-transfer zones, customers should not walk through wide shopping-floor aisles without a cart.",
    "abstraction": {
      "state_properties": {
        "wideShoppingFloor": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "entranceCartZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessExceptionZone": {
          "or": [
            "entranceCartZone",
            "aisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "wideShoppingFloor",
          {
            "not": "cartlessExceptionZone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "Whenever a customer parks a cart at the mouth of a narrow aisle, they are obliged to retrieve it before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "aisleMouth",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveParkedCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "aisleMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveParkedCart"
    }
  },
  {
    "id": "no_leaving_aisle_mouth_on_foot",
    "text": "From a narrow-aisle mouth, a customer without a cart may only go into the narrow aisle or retrieve the cart, not leave laterally or southward into the store.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "aisleMouth",
          {
            "or": [
              "E",
              "S",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_cart_accessible_shelves",
    "text": "Interactions with shelf faces in cart-accessible aisles must be done while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "narrow_shelf_interaction_on_foot",
    "text": "Interactions with shelves inside single-file aisles must be performed on foot, without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileAisle",
          "hasCart"
        ]
      }
    }
  }
]
